 void createFolder(String folder)throws Exception {var process=new ProcessBuilder("/usr/bin/python3",providerScript.toString(),"--config",config.toString(),"--create-folder",folder).redirectErrorStream(true).redirectOutput(evidence.resolve("knowledge-folder.log").toFile()).start();if(!process.waitFor(10,TimeUnit.SECONDS)){process.destroyForcibly();process.waitFor(5,TimeUnit.SECONDS);throw new IllegalStateException("Controlled folder administration timed out");}assertEquals(0,process.exitValue(),"Exact controlled folder required");}
 void grant(String actor)throws Exception {grant(actor,"controlled-root");}
 void grant(String actor,String folder)throws Exception {var grant=new ProcessBuilder("/usr/bin/python3",providerScript.toString(),"--config",config.toString(),"--grant-actor",actor,"--grant-folder",folder,"--grant-read","--grant-publish").redirectErrorStream(true).redirectOutput(evidence.resolve("knowledge-grant.log").toFile()).start();if(!grant.waitFor(10,TimeUnit.SECONDS)){grant.destroyForcibly();grant.waitFor(5,TimeUnit.SECONDS);throw new IllegalStateException("Controlled grant timed out");}assertEquals(0,grant.exitValue(),"Actual controlled actor grant required");}
 private static void write(Path path,String text)throws Exception {try(var channel=Files.newByteChannel(path,Set.of(StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE),java.nio.file.attribute.PosixFilePermissions.asFileAttribute(java.nio.file.attribute.PosixFilePermissions.fromString("rw-------")))){channel.write(java.nio.ByteBuffer.wrap(text.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}}
 public void close()throws Exception {if(process==null){assertTrue(retained.isAlive());return;}if(process.isAlive()){process.destroy();if(!process.waitFor(5,TimeUnit.SECONDS)){process.destroyForcibly();assertTrue(process.waitFor(5,TimeUnit.SECONDS));}}Files.writeString(evidence.resolve("knowledge-closed.json"),json.writeValueAsString(Map.of("pid",process.pid(),"alive",process.isAlive(),"port",port,"store",store.toString(),"storeRetained",Files.isRegularFile(store),"closedUtc",Instant.now().toString())));}
